import numpy as np
from dateutil.parser import parse
import math
from datetime import datetime, timedelta

MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])


def task_func(date_str, from_tz, to_tz):
    if not isinstance(date_str, str) or not date_str.strip():
        raise ValueError("date_str must be a non-empty string")

    try:
        dt = parse(date_str)
    except Exception as exc:
        raise ValueError(f"Invalid date_str: {date_str!r}") from exc

    try:
        from_zone = pytz.timezone(str(from_tz))
        to_zone = pytz.timezone(str(to_tz))
    except Exception as exc:
        raise ValueError("Invalid timezone name") from exc

    if dt.tzinfo is None:
        try:
            dt = from_zone.localize(dt, is_dst=None)
        except pytz.AmbiguousTimeError:
            dt = from_zone.localize(dt, is_dst=False)
        except pytz.NonExistentTimeError:
            try:
                dt = from_zone.localize(dt, is_dst=False)
            except Exception:
                try:
                    dt = from_zone.localize(dt, is_dst=True)
                except Exception:
                    dt = from_zone.localize(dt + timedelta(hours=1), is_dst=True)
    else:
        dt = dt.astimezone(from_zone)

    local_dt = dt.astimezone(to_zone)
    utc_dt = local_dt.astimezone(pytz.UTC)

    years = np.sort(np.unique(MOON_PHASES_YEARS.astype(int)))
    if years.size == 0:
        reference_year = 2001
    elif years.size == 1:
        reference_year = int(years[0])
    else:
        diffs = np.diff(years)
        cycle_years = int(np.gcd.reduce(diffs)) if diffs.size else 7
        if cycle_years <= 0:
            cycle_years = 7

        target_year = int(local_dt.year)

        if years[0] <= target_year <= years[-1]:
            reference_year = int(years[np.argmin(np.abs(years - target_year))])
        elif target_year < years[0]:
            steps = math.floor((target_year - int(years[0])) / cycle_years)
            reference_year = int(years[0] + steps * cycle_years)
        else:
            steps = math.floor((target_year - int(years[-1])) / cycle_years)
            reference_year = int(years[-1] + steps * cycle_years)

    # Use a known approximate new moon epoch and shift it by whole 7-year cycles.
    base_epoch = pytz.UTC.localize(datetime(2001, 1, 24, 13, 0, 0))
    reference_epoch = base_epoch.replace(year=reference_year)

    synodic_month = 29.53058867  # days
    days_since_ref = (utc_dt - reference_epoch).total_seconds() / 86400.0
    cycle_pos = (days_since_ref / synodic_month) % 1.0

    # Map cycle position to illumination-like phase:
    # 0.0 -> new moon, 1.0 -> full moon
    phase = 0.5 * (1.0 - math.cos(2.0 * math.pi * cycle_pos))

    return float(max(0.0, min(1.0, phase)))
