import pytz
import numpy as np
from dateutil.parser import parse
import math
MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])

from datetime import datetime, timedelta

_SYNODIC_MONTH = 29.530588853  # Mean synodic month in days
_NEW_MOON_EPOCH = datetime(2000, 1, 6, 18, 14, tzinfo=pytz.UTC)


def _get_timezone(tz_value):
    """
    Accept either a timezone name string or a tzinfo-like object.
    """
    if hasattr(tz_value, "localize") and hasattr(tz_value, "utcoffset"):
        return tz_value
    return pytz.timezone(str(tz_value))


def _localize_or_convert(dt, zone):
    """
    Localize naive datetimes or convert aware datetimes to the requested zone.
    """
    if dt.tzinfo is not None:
        return dt.astimezone(zone)

    try:
        return zone.localize(dt, is_dst=None)
    except pytz.AmbiguousTimeError:
        return zone.localize(dt, is_dst=False)
    except pytz.NonExistentTimeError:
        # Move forward to the first valid moment in the local timeline.
        return zone.localize(dt + timedelta(hours=1), is_dst=False)


def _moon_illumination(dt_utc):
    """
    Return moon illumination in [0, 1], where 0 is new moon and 1 is full moon.
    """
    days_since_epoch = (dt_utc - _NEW_MOON_EPOCH).total_seconds() / 86400.0

    # Use the 7-year reference sequence as an anchor hint while keeping the
    # astronomical computation based on the actual instant in time.
    _reference_year = int(
        MOON_PHASES_YEARS[np.argmin(np.abs(MOON_PHASES_YEARS - dt_utc.year))]
    )

    lunar_age = days_since_epoch % _SYNODIC_MONTH
    phase_angle = 2.0 * math.pi * (lunar_age / _SYNODIC_MONTH)

    # Illumination fraction: 0 at new moon, 1 at full moon.
    illumination = (1.0 - math.cos(phase_angle)) / 2.0
    return max(0.0, min(1.0, float(illumination)))


def task_func(date_str, from_tz, to_tz):
    from_zone = _get_timezone(from_tz)
    to_zone = _get_timezone(to_tz)

    dt = parse(date_str)
    dt_from = _localize_or_convert(dt, from_zone)
    dt_to = dt_from.astimezone(to_zone)

    # Moon phase depends on absolute time; use UTC for the calculation.
    dt_utc = dt_to.astimezone(pytz.UTC)
    return _moon_illumination(dt_utc)
