    def _convert_numeric(series):
        if pd.api.types.is_numeric_dtype(series):
            return series.astype(float)
        converted = pd.to_numeric(series, errors="coerce")
        if converted.notna().sum() == series.notna().sum():
            return converted.astype(float)
        return series

    df = df.apply(_convert_numeric)

    missing_columns = [col for col in columns if col not in df.columns]
    if missing_columns:
        raise KeyError(f"Missing columns in CSV: {missing_columns}")

    plot_data = df.loc[:, columns].apply(pd.to_numeric, errors="coerce").astype(float)

    ax = plot_data.plot()

    cube_root_series = pd.Series(
        np.cbrt(plot_data.to_numpy().ravel()),
